import type { Theme } from '@mui/material/styles';

export interface SvTokens {
  accent: string;
  accentHover: string;
  surface: string;
  surfaceHover: string;
  stroke: string;
  green: string;
  greenHover?: string;
  focus: string;
}

declare module '@mui/material/styles' {
  interface Theme {
    sv: SvTokens;
  }
  interface ThemeOptions {
    sv?: Partial<SvTokens>;
  }
  interface ThemeVars {
    sv?: SvTokens;
  }
}

/** Supports plain MUI themes without requiring the consumer to add StreamVi tokens. */
export function svTokens(theme: Theme): SvTokens {
  const palette = (theme.vars ?? theme).palette;
  return (
    theme.vars?.sv ??
    theme.sv ?? {
      accent: palette.primary.main,
      accentHover: palette.primary.light,
      surface: palette.action.hover,
      surfaceHover: palette.action.selected,
      stroke: palette.divider,
      green: palette.success.main,
      greenHover: palette.success.dark,
      focus: palette.primary.main,
    }
  );
}
